import{c as s}from"./app.756eaed4.js";import{_ as n}from"./plugin-vue_export-helper.21dcd24c.js";const a={},t=s(`<h1 id="configuring-ims-connections" tabindex="-1"><a class="header-anchor" href="#configuring-ims-connections" aria-hidden="true">#</a> Configuring IMS connections</h1><p>The <code>ims.connections.json</code> file is the central configuration file for IMS database connections. It is located in the IMS workspace directory and supports a range of optional parameters that control connection behavior, data visibility, performance, SSL security, and diagnostics.</p><h2 id="overview" tabindex="-1"><a class="header-anchor" href="#overview" aria-hidden="true">#</a> Overview</h2><p>When you create a connection using the <strong>IMS Connections</strong> view, the extension generates a minimal <code>ims.connections.json</code> entry. You can edit this file directly to apply any of the advanced settings described in this topic.</p><h2 id="connection-properties" tabindex="-1"><a class="header-anchor" href="#connection-properties" aria-hidden="true">#</a> Connection properties</h2><p>The following properties apply to each named connection entry under <code>profiles</code>:</p><table><thead><tr><th>Property</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>dataStoreServer</code></td><td>String</td><td>The hostname or IP address of the IMS Connect server.</td></tr><tr><td><code>portNumber</code></td><td>Integer</td><td>The TCP/IP port number used to communicate with IMS Connect.</td></tr><tr><td><code>databaseName</code></td><td>String</td><td>The name of the database metadata representing the target IMS database.</td></tr><tr><td><code>metadataSource</code></td><td>String</td><td>The source of database metadata. Accepted values: <code>&quot;IMS Catalog&quot;</code>.</td></tr><tr><td><code>fetchSize</code></td><td>Integer</td><td>Number of rows fetched per round trip to the server.</td></tr><tr><td><code>maxRows</code></td><td>Integer</td><td>Maximum number of rows returned by a query.</td></tr><tr><td><code>imsId</code></td><td>String</td><td>The identifier of the target IMS system.</td></tr><tr><td><code>imsPlexName</code></td><td>String</td><td>The name of the IMS plex that the target IMS system belongs to.</td></tr></tbody></table><h2 id="show-ims-catalogs" tabindex="-1"><a class="header-anchor" href="#show-ims-catalogs" aria-hidden="true">#</a> Show IMS Catalogs</h2><p>Control visibility of system-level IMS catalog DBDs and PSBs (those with the <code>DFSC</code> prefix) by setting <code>showIMSCatalogs</code> in your connection configuration:</p><div class="language-json ext-json line-numbers-mode"><pre class="language-json"><code><span class="token punctuation">{</span>
  <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;MyConnection&quot;</span><span class="token punctuation">,</span>
  <span class="token property">&quot;showIMSCatalogs&quot;</span><span class="token operator">:</span> <span class="token boolean">false</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>The default value is <code>false</code>, which hides system catalogs. Set to <code>true</code> to reveal them.</p><h2 id="ssl-certificate-management" tabindex="-1"><a class="header-anchor" href="#ssl-certificate-management" aria-hidden="true">#</a> SSL certificate management</h2><p>SSL certificate attributes can be configured for a database profile in <code>ims.connections.json</code> to establish secure connections to IMS.</p><div class="language-json ext-json line-numbers-mode"><pre class="language-json"><code><span class="token punctuation">{</span>
  <span class="token property">&quot;profiles&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
    <span class="token property">&quot;imsdb&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
      <span class="token property">&quot;databaseConnectionName&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
        <span class="token property">&quot;dataStoreServer&quot;</span><span class="token operator">:</span> <span class="token string">&quot;imshost.example.com&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;portNumber&quot;</span><span class="token operator">:</span> <span class="token number">8895</span><span class="token punctuation">,</span>
        <span class="token property">&quot;databaseName&quot;</span><span class="token operator">:</span> <span class="token string">&quot;IMSPROD1&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;sslConnection&quot;</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span>
        <span class="token property">&quot;sslKeyStoreType&quot;</span><span class="token operator">:</span> <span class="token string">&quot;JKS&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;sslKeyStoreLocation&quot;</span><span class="token operator">:</span> <span class="token string">&quot;/path/to/keystore.jks&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;sslTrustStoreLocation&quot;</span><span class="token operator">:</span> <span class="token string">&quot;/path/to/truststore.jks&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;sslKeyStorePassword&quot;</span><span class="token operator">:</span> <span class="token string">&quot;&lt;keystore-password&gt;&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;sslTrustStorePassword&quot;</span><span class="token operator">:</span> <span class="token string">&quot;&lt;truststore-password&gt;&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;sslSecureSocketProtocol&quot;</span><span class="token operator">:</span> <span class="token string">&quot;TLS&quot;</span>
      <span class="token punctuation">}</span>
    <span class="token punctuation">}</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><table><thead><tr><th>Attribute</th><th>Description</th></tr></thead><tbody><tr><td><code>sslConnection</code></td><td>Set to <code>true</code> to enable SSL for the connection.</td></tr><tr><td><code>sslKeyStoreType</code></td><td>The key store format. Accepted value: <code>&quot;JKS&quot;</code>.</td></tr><tr><td><code>sslKeyStoreLocation</code></td><td>Absolute path to the key store file (<code>.jks</code>).</td></tr><tr><td><code>sslTrustStoreLocation</code></td><td>Absolute path to the trust store file (<code>.jks</code>).</td></tr><tr><td><code>sslKeyStorePassword</code></td><td>Password for the key store.</td></tr><tr><td><code>sslTrustStorePassword</code></td><td>Password for the trust store.</td></tr><tr><td><code>sslSecureSocketProtocol</code></td><td>The SSL protocol to use. Recommended value: <code>&quot;TLS&quot;</code> or <code>&quot;TLSv1.2&quot;</code>.</td></tr></tbody></table><blockquote><p><strong>Note:</strong> Store key store and trust store files in a secure location. Avoid committing passwords directly to source control. Consider using VS Code secret storage or environment variables to manage credentials.</p></blockquote><h2 id="tracing-and-diagnostics" tabindex="-1"><a class="header-anchor" href="#tracing-and-diagnostics" aria-hidden="true">#</a> Tracing and diagnostics</h2><p>Tracing can be enabled on a per-connection basis to capture detailed diagnostic information about a connection&#39;s activity. Trace output is written to a file in the directory specified by <code>traceDirectory</code>.</p><div class="language-json ext-json line-numbers-mode"><pre class="language-json"><code><span class="token punctuation">{</span>
  <span class="token property">&quot;traceFile&quot;</span><span class="token operator">:</span> <span class="token string">&quot;imsdb.log&quot;</span><span class="token punctuation">,</span>
  <span class="token property">&quot;traceFileAppend&quot;</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span>
  <span class="token property">&quot;traceDirectory&quot;</span><span class="token operator">:</span> <span class="token string">&quot;/path/to/logs&quot;</span><span class="token punctuation">,</span>
  <span class="token property">&quot;traceLevel&quot;</span><span class="token operator">:</span> <span class="token number">-1</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><table><thead><tr><th>Attribute</th><th>Description</th></tr></thead><tbody><tr><td><code>traceFile</code></td><td>Name of the trace output file.</td></tr><tr><td><code>traceFileAppend</code></td><td>Set to <code>true</code> to append to an existing trace file rather than overwriting it.</td></tr><tr><td><code>traceDirectory</code></td><td>Absolute path to the directory where the trace file is written.</td></tr><tr><td><code>traceLevel</code></td><td>Verbosity level for trace output. Use <code>-1</code> for maximum detail.</td></tr></tbody></table><h2 id="example-ims-connections-json" tabindex="-1"><a class="header-anchor" href="#example-ims-connections-json" aria-hidden="true">#</a> Example: ims.connections.json</h2><p>The following example shows a fully configured <code>ims.connections.json</code> file. It includes an <code>imsdatabases</code> profile with multiple named database connections\u2014one standard, one with SSL and tracing enabled\u2014and an <code>imsconnects</code> profile with IMS system identifier and IMS plex name properties.</p><div class="language-json ext-json line-numbers-mode"><pre class="language-json"><code><span class="token punctuation">{</span>
  <span class="token property">&quot;profiles&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
    <span class="token property">&quot;imsdatabases&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
      <span class="token property">&quot;myConnection&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
        <span class="token property">&quot;dataStoreServer&quot;</span><span class="token operator">:</span> <span class="token string">&quot;imshost1.example.com&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;portNumber&quot;</span><span class="token operator">:</span> <span class="token number">5555</span><span class="token punctuation">,</span>
        <span class="token property">&quot;databaseName&quot;</span><span class="token operator">:</span> <span class="token string">&quot;IMSPROD1&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;metadataSource&quot;</span><span class="token operator">:</span> <span class="token string">&quot;IMS Catalog&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;fetchSize&quot;</span><span class="token operator">:</span> <span class="token number">100</span><span class="token punctuation">,</span>
        <span class="token property">&quot;maxRows&quot;</span><span class="token operator">:</span> <span class="token number">500</span>
      <span class="token punctuation">}</span><span class="token punctuation">,</span>
      <span class="token property">&quot;myConnection2&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
        <span class="token property">&quot;dataStoreServer&quot;</span><span class="token operator">:</span> <span class="token string">&quot;imshost2.example.com&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;portNumber&quot;</span><span class="token operator">:</span> <span class="token number">5555</span><span class="token punctuation">,</span>
        <span class="token property">&quot;databaseName&quot;</span><span class="token operator">:</span> <span class="token string">&quot;IMSTEST1&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;metadataSource&quot;</span><span class="token operator">:</span> <span class="token string">&quot;IMS Catalog&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;fetchSize&quot;</span><span class="token operator">:</span> <span class="token number">100</span><span class="token punctuation">,</span>
        <span class="token property">&quot;maxRows&quot;</span><span class="token operator">:</span> <span class="token number">500</span>
      <span class="token punctuation">}</span><span class="token punctuation">,</span>
      <span class="token property">&quot;ssl-connection&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
        <span class="token property">&quot;dataStoreServer&quot;</span><span class="token operator">:</span> <span class="token string">&quot;imshost3.example.com&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;portNumber&quot;</span><span class="token operator">:</span> <span class="token number">8895</span><span class="token punctuation">,</span>
        <span class="token property">&quot;databaseName&quot;</span><span class="token operator">:</span> <span class="token string">&quot;IMSSEC1&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;fetchSize&quot;</span><span class="token operator">:</span> <span class="token number">100</span><span class="token punctuation">,</span>
        <span class="token property">&quot;maxRows&quot;</span><span class="token operator">:</span> <span class="token number">500</span><span class="token punctuation">,</span>
        <span class="token property">&quot;sslConnection&quot;</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span>
        <span class="token property">&quot;sslKeyStoreType&quot;</span><span class="token operator">:</span> <span class="token string">&quot;JKS&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;sslKeyStoreLocation&quot;</span><span class="token operator">:</span> <span class="token string">&quot;/path/to/keystore.jks&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;sslKeyStorePassword&quot;</span><span class="token operator">:</span> <span class="token string">&quot;&lt;keystore-password&gt;&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;sslTrustStoreLocation&quot;</span><span class="token operator">:</span> <span class="token string">&quot;/path/to/truststore.jks&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;sslTrustStorePassword&quot;</span><span class="token operator">:</span> <span class="token string">&quot;&lt;truststore-password&gt;&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;sslSecureSocketProtocol&quot;</span><span class="token operator">:</span> <span class="token string">&quot;TLSv1.2&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;traceFile&quot;</span><span class="token operator">:</span> <span class="token string">&quot;imsdb.log&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;traceFileAppend&quot;</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span>
        <span class="token property">&quot;traceDirectory&quot;</span><span class="token operator">:</span> <span class="token string">&quot;/path/to/logs&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;traceLevel&quot;</span><span class="token operator">:</span> <span class="token number">-1</span><span class="token punctuation">,</span>
        <span class="token property">&quot;metadataSource&quot;</span><span class="token operator">:</span> <span class="token string">&quot;IMS Catalog&quot;</span>
      <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token property">&quot;imsconnects&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
      <span class="token property">&quot;myImsConnect&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span>
        <span class="token property">&quot;dataStoreServer&quot;</span><span class="token operator">:</span> <span class="token string">&quot;imshost4.example.com&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;portNumber&quot;</span><span class="token operator">:</span> <span class="token number">9989</span><span class="token punctuation">,</span>
        <span class="token property">&quot;imsId&quot;</span><span class="token operator">:</span> <span class="token string">&quot;IMS1&quot;</span><span class="token punctuation">,</span>
        <span class="token property">&quot;imsPlexName&quot;</span><span class="token operator">:</span> <span class="token string">&quot;PLEX1&quot;</span>
      <span class="token punctuation">}</span>
    <span class="token punctuation">}</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br></div></div>`,23);function e(o,p){return t}var l=n(a,[["render",e]]);export{l as default};
